module top_module(
    input clk,
    input ce,
    input [3:0] d,
    input [3:0] adr0,
    input [3:0] adr1,
    input [3:0] adr2,
    input [3:0] adr3,
    output reg [3:0] q
);reg [3:0] sr [0:7];

always @ (posedge clk) begin
    if (ce) begin
        sr[0] <= d;
        sr[1] <= sr[0];
        sr[2] <= sr[1];
        sr[3] <= sr[2];
        sr[4] <= sr[3];
        sr[5] <= sr[4];
        sr[6] <= sr[5];
        sr[7] <= sr[6];
    end
end

always @ (*) begin
    case ({adr3, adr2, adr1, adr0})
        4'b0000: q = sr[0];
        4'b0001: q = sr[1];
        4'b0010: q = sr[2];
        4'b0011: q = sr[3];
        4'b0100: q = sr[4];
        4'b0101: q = sr[5];
        4'b0110: q = sr[6];
        4'b0111: q = sr[7];
        default: q = 4'b0000;
    endcase
end

endmodule

