                stage <= 2;
            end
            2: begin
                stage3_out = {stage2_out[2], stage2_out[1], stage2_out[0], 1'b0};
                stage <= 3;
            end
            3: begin
                stage4_out = stage3_out[3:2] + 2'b10;
                stage <= 4;
            end
            4: begin
                sqrt <= stage4_out; // Assign to sqrt here
                stage <= 0; // Reset stage after completion
            end
        endcase
    end
