module top_module(
  input clk_freq,
  input reset,
  output reg clk
);parameter fmax = 100000000; // maximum frequency of the clock signal that can be generated
parameter fmin = 1000000; // minimum frequency of the clock signal that can be generated

reg [31:0] count = 0; // counter to count the number of clock cycles
reg [31:0] clk_div = 0; // counter to divide the clock frequency
reg [31:0] clk_div_max = 0; // maximum value of clk_div
reg [31:0] clk_div_min = 0; // minimum value of clk_div
reg [31:0] clk_div_target = 0; // target value of clk_div
reg [31:0] clk_freq_actual = 0; // actual clock frequency generated

always @(posedge clk_freq or posedge reset) begin
  if (reset) begin
    count <= 0;
    clk_div <= 0;
    clk_div_max <= fmax/fmin;
    clk_div_min <= 1;
    clk_div_target <= 0;
    clk_freq_actual <= 0;
  end else begin
    count <= count + 1;
    if (count == fmax/fmin) begin
      count <= 0;
      clk_div <= clk_div + 1;
      if (clk_div > clk_div_max) begin
        clk_div <= clk_div_max;
      end
      if (clk_div < clk_div_min) begin
        clk_div <= clk_div_min;
      end
      clk_freq_actual <= fmax/clk_div;
      if (clk_freq_actual < fmin) begin
        clk_div_target <= clk_div + 1;
      end else if (clk_freq_actual > fmax) begin
        clk_div_target <= clk_div - 1;
      end else begin
        clk_div_target <= clk_div;
      end
    end
  end
end

always @(posedge clk_freq or posedge reset) begin
  if (reset) begin
    clk <= 0;
  end else begin
    if (clk_div == clk_div_target) begin
      clk <= ~clk;
    end
  end
end

