description:
Design a sequence detector that recognizes a specific pattern in a serial input stream. It operates based on a finite state machine with four states, cycling through them based on the input signal. When the desired sequence is detected within the input, it sets the output high. The module captures transitions on the rising edge of the input signal, maintaining state and producing an output that indicates detection of the specified pattern.
module top_module(
  input in,
  output out
);

code:
module top_module(
  input in,
  output out
);parameter n = 4; // number of bits in the input stream

reg [1:0] state;
reg out_reg;

always @(posedge in) begin
  case(state)
    2'b00: if(in) state <= 2'b01; else state <= 2'b00;
    2'b01: if(in) state <= 2'b10; else state <= 2'b00;
    2'b10: if(in) begin
             state <= 2'b11;
             out_reg <= 1;
           end
           else begin
             state <= 2'b00;
             out_reg <= 0;
           end
    2'b11: if(in) state <= 2'b10; else state <= 2'b01;
  endcase
end

assign out = out_reg;

endmodule

