module binary_counter (CLK, RST, COUNT);
input CLK, RST;
output reg [3:0] COUNT;

always @(posedge CLK or posedge RST) begin
	if (RST) begin
		COUNT <= 4'b0000;
	end
	else begin
		COUNT <= COUNT + 1;
	end
end

endmodule

