        if (delta_channels != old_delta) begin
            data[35:0] <= timer[35:0];
            data[39:36] <= delta_channels;
            data[44:40] <= 0;
            data[45] <= 1;
            data[46] <= (timer == 36'b0) ? 1'b1 : 1'b0;
            ready <= capture_operate;
            old_delta <= delta_channels;
