description:
Design a one-bit asynchronous reset signal generator that outputs a LOW signal (Reset_S) when the internal state Qok is HIGH. The output Qok follows the state of Qmeta, which is set to LOW on reset and transitioned to HIGH on each clock cycle thereafter. The module outputs a reset signal that can be used in digital circuits to initialize components properly upon reset.
module top_module(
    input   clk,
    input   rst,
    output  Reset_S
    );

code:
module top_module(
    input   clk,
    input   rst,
    output  Reset_S
    );reg    Qok, Qmeta;

    assign  Reset_S = ~Qok;

    always @(posedge clk, posedge rst)
        if(rst)
            Qmeta <= 1'b0;
        else
            Qmeta <= 1'b1;

    always @(posedge clk)
        Qok <= Qmeta;
endmodule

