module top_module(clock0, clock1, address_a, data_a, rden_a, wren_a, byteena_a, q_a, addressstall_a, address_b, data_b, rden_b, wren_b, byteena_b, q_b, addressstall_b, clocken0, clocken1, clocken2, clocken3, aclr0, aclr1, eccstatus);parameter lpm_type = "altsyncram";
parameter operation_mode = "dual_port";
parameter ram_block_type = "auto";
parameter intended_device_family = "auto";
parameter power_up_uninitialized = "false";
parameter read_during_write_mode_mixed_ports = "dontcare";
parameter byte_size = 8;
parameter widthad_a = 1;
parameter width_a = 1;
parameter width_byteena_a = 1;
parameter numwords_a = 1;
parameter clock_enable_input_a = "clocken0";
parameter widthad_b = 1;
parameter width_b = 1;
parameter width_byteena_b = 1; // Added width_byteena_b parameter
parameter numwords_b = 1;
parameter address_aclr_b = "aclr0";
parameter address_reg_b = "";
parameter outdata_aclr_b = "aclr0";
parameter outdata_reg_b = "";
parameter clock_enable_input_b = "clocken0";
parameter clock_enable_output_b = "clocken0";

input clock0, clock1;
input [widthad_a-1:0] address_a;
input [width_a-1:0] data_a;
input rden_a;
input wren_a;
input [(width_a/8)-1:0] byteena_a;
input addressstall_a;

output reg [width_a-1:0] q_a; // Changed to output reg

input wren_b;
input rden_b;
input [widthad_b-1:0] address_b;
input [width_b-1:0] data_b;
input [(width_b/8)-1:0] byteena_b;
input addressstall_b;

output reg [width_b-1:0] q_b; // Changed to output reg

input clocken0;
input clocken1;
input clocken2;
input clocken3;

input aclr0;
input aclr1;

output eccstatus;

reg [width_a-1:0] ram_a [0:numwords_a-1]; // Array declaration
reg [width_b-1:0] ram_b [0:numwords_b-1]; // Array declaration

always @(posedge clock0) begin
    if (aclr0) begin
        integer i;
        for (i = 0; i < numwords_a; i = i + 1) begin
            ram_a[i] <= 0; // Clear entire RAM for port A
        end
    end else if (wren_a && address_a < numwords_a) begin
        ram_a[address_a] <= (byteena_a) ? data_a : ram_a[address_a]; // Writing based on byteena_a
    end
end

always @(posedge clock1) begin
    if (aclr1) begin
        integer i;
        for (i = 0; i < numwords_b; i = i + 1) begin
            ram_b[i] <= 0; // Clear entire RAM for port B
        end
    end else if (wren_b && address_b < numwords_b) begin
        ram_b[address_b] <= (byteena_b) ? data_b : ram_b[address_b]; // Writing based on byteena_b
    end
end

always @* begin
    q_a = (rden_a && address_a < numwords_a) ? ram_a[address_a] : 0;
    q_b = (rden_b && address_b < numwords_b) ? ram_b[address_b] : 0;
end

endmodule

