	else if (data_in[3])
		encoded_out = 3'b011;
	else if (data_in[2])
		encoded_out = 3'b010;
	else if (data_in[1])
		encoded_out = 3'b001;
	else if (data_in[0])
		encoded_out = 3'b000;
	else
		encoded_out = 3'b000;
end
endmodule

