module top_module(output wire [WIDTH-1:0] DOUTB, // Declare DOUTB with direction
    input wire ENA,                // Declare ENA with direction
    input wire clka,               // Declare clka with direction
    input wire ENB,                // Declare ENB with direction
    input wire clkb,               // Declare clkb with direction
    input wire [ADDR_WIDTH-1:0] addra, // Declare addra with direction
    input wire [ADDR_WIDTH-1:0] addrb, // Declare addrb with direction
    input wire [WIDTH-1:0] dina);// Declare dina with direction

  parameter WIDTH = 1; // Width of the data bus
  parameter DEPTH = 1024; // Depth of the memory
  parameter ADDR_WIDTH = $clog2(DEPTH); // Address width

  // Memory array
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  // Write enable and address
  reg w_en;
  reg [ADDR_WIDTH-1:0] w_addr;

  // Read enable and address
  reg r_en;
  reg [ADDR_WIDTH-1:0] r_addr;

  // Data input
  reg [WIDTH-1:0] din;

  // Generate write enable signal
  assign w_en = ENA;

  // Generate read enable signal
  assign r_en = ENB;

  // Assign write address
  always @(posedge clka) begin
    if (w_en) begin
      w_addr <= addra;
      mem[w_addr] <= dina;  // Write data during address assignment
    end
  end

  // Assign read address
  always @(posedge clkb) begin
    if (r_en) begin
      r_addr <= addrb;
    end
  end

  // Read data from memory
  assign DOUTB = (r_en) ? mem[r_addr] : {WIDTH{1'bz}}; // Tri-state output

endmodule

